}
,
[4112] = {
["description"] = "Besiegt zusätzlich zu Henkerin Jerensi, dem obersten Zauberer Vandorallen und der Bö der Vergeltung alle Gegner in der Schanze der Abgeschiedenen (Veteranen) innerhalb von 25 Minuten. Die Zeit läuft, sobald Ihr die erste Gruppe von Gegnern angreift.",
["name"] = "Kurzer Prozess",
}
,
[4113] = {
["description"] = "Besiegt zusätzlich zu Henkerin Jerensi, dem obersten Zauberer Vandorallen und der Bö der Vergeltung alle Gegner in der Schanze der Abgeschiedenen (Veteranen), ohne dass ein Gruppenmitglied getötet wird.",
["name"] = "Geistlos",
}
,
