}
,
[4115] = {
["description"] = "Besiegt zusätzlich zu Henkerin Jerensi, dem obersten Zauberer Vandorallen und der Bö der Vergeltung alle Gegner in der Schanze der Abgeschiedenen (Veteranen), nachdem Ihr das Herausforderungsbanner gehisst habt, innerhalb von 25 Minuten, ohne dass ein Gruppenmitglied getötet wird. Die Zeit läuft, sobald Ihr in einen Kampf verwickelt werdet.",
["name"] = "Rachebruch",
}
,
[4116] = {
["description"] = "Besiegt Henkerin Jerensi in der Schanze der Abgeschiedenen (Veteranen), ohne von ihren Stachelfallen getroffen zu werden.",
