}
,
[4117] = {
["description"] = "Nehmt während des Kampfes gegen die Bö der Vergeltung eine Feuer-, Eis- oder Blitzkugel auf, bevor es sich zu feuriger Eruption, gefrierender Scherbe oder Blitzexplosion entwickelt, und besiegt die Bö der Vergeltung in der Schanze der Abgeschiedenen.",
["name"] = "Unfragmentiert",
}
,
[4120] = {
["description"] = "Besiegt die Bö der Vergeltung in der Schanze der Abgeschiedenen (Veteranen), nachdem Ihr das Herausforderungsbanner gehisst habt, mit einer vollen Gruppe aus 4 Spielern, erst nachdem jedes Mitglied Eurer Gruppe eine elementare Kugel in jeder Farbe aufgesammelt hat.",
["name"] = "Den Elementen ausgeliefert",
}
,
[4121] = {
["description"] = "Besiegt während eines Laufs in der Schanze der Abgeschiedenen Wachhauptmann Paratius, Dozent Domitius und Eliana Albus, bevor Ihr die Bö der Vergeltung besiegt.",
