}
,
[1391] = {
["description"] = "Schließt alle Errungenschaften im Zusammenhang mit dem Sieg über Rakkhat, den Reißzahn Lorkhajs, im Schlund von Lorkhaj (Veteranen) ab.",
["name"] = "Champion der Monde",
}
,
[1392] = {
["description"] = "Schließt den Schlund von Lorkhaj (Veteranen) ab, ohne dass ein Gruppenmitglied getötet wird.",
["name"] = "Unbefleckter Sieg",
}
,
[1394] = {
