["name"] = "Fünf-Finger-Rabatt",
}
,
[1402] = {
["description"] = "Entkommt dem Gesetz, indem Ihr von der Fähigkeit „zeitiges Entkommen“ der Diebesgilde, sowie dem freundlichen Strauchdieb, Gebrauch macht.",
["name"] = "Und weg waren sie",
}
,
[1404] = {
