}
,
[1569] = {
["description"] = "Besiegt die Schwarmmutter und die Flüsterin in den Spindeltiefen I (Veteranen), ohne dass ein Gruppenmitglied getötet wird.",
["name"] = "Überlebender der Spindeltiefen I",
}
,
[1570] = {
["description"] = "Besiegt die Flüsterin in den Spindeltiefen I (Veteranen), nachdem Ihr die Schriftrolle der Ruhmreichen Schlacht aktiviert habt.",
["name"] = "Endlich Stille",
}
,
[1571] = {
["description"] = "Besiegt Mortine den Verrückten, Blutbrut, Praxin Douare, die drei Fleischatronachen, Urvan Veleth und Vorenor Winterkind in den Spindeltiefen II.",
["name"] = "Sieger der Spindeltiefen II",
}
,
[1572] = {
["description"] = "Besiegt Mortine den Verrückten, die Blutbrut, Praxin Douare, das Trio aus Fleischatronachen, Urvan Veleth und Vorenor Winterkind in den Spindeltiefen II (Veteranen), ohne dass ein Gruppenmitglied getötet wird.",
["name"] = "Überlebender der Spindeltiefen II",
}
,
[1573] = {
["description"] = "Besiegt Akash gra-Mal, den uralten Zweigling, Würgedorn, Nenesh gro-Mal, Blattgärer und Stiftsvogt Oraneth im Eldengrund I (Veteranen).",
["name"] = "Eroberer des Eldengrunds I",
}
,
[1576] = {
["description"] = "Besiegt Akash gra-Mal, den uralten Zweigling, Würgedorn, Nenesh gro-Mal, Blattgärer und Stiftsvogt Oraneth im Eldengrund I (Veteranen) innerhalb von 20 Minuten, nachdem das Verlies gestartet wurde. Die Zeit läuft, sobald Ihr die erste Gruppe Thalmor angegriffen habt.",
["name"] = "Assassine des Eldengrunds I",
}
,
[1577] = {
["description"] = "Besiegt Akash gra-Mal, den uralten Zweigling, Würgedorn, Nenesh gro-Mal, Blattgärer und Stiftsvogt Oraneth im Eldengrund I (Veteranen), ohne dass ein Gruppenmitglied getötet wird.",
