}
,
[1578] = {
["description"] = "Besiegt Stiftsvogt Oraneth im Eldengrund I (Veteranen), nachdem Ihr die Schriftrolle der Ruhmreichen Schlacht aktiviert habt.",
["name"] = "Stiftsvogtsplünderer",
}
,
[1579] = {
["description"] = "Besiegt Dubroze den Heimsucher, Dunkelwurz, Azara die Furchtbringerin, Düsterlicht, die Schattenwache und Bogdan die Nachtflamme im Eldengrund II.",
["name"] = "Sieger des Eldengrunds II",
}
,
[1580] = {
["description"] = "Besiegt Dubroze den Heimsucher, Dunkelwurz, Azara die Furchtbringerin, Düsterlicht, die Schattenwache und Bogdan die Nachtflamme in Eldenwurz II, ohne dass ein Gruppenmitglied getötet wird.",
["name"] = "Überlebender des Eldengrunds II",
}
,
[1581] = {
["description"] = "Besiegt Oberhirtin Neloren, Vorarbeiter Llothan, den Schwarmfürsten, den Höhlenpatriarchen, den Wachposten von Rkugamz und die Schnittersphäre in den Dunkelschattenkavernen I (Veteranen).",
["name"] = "Eroberer der Dunkelschattenkavernen I",
}
,
[1584] = {
["description"] = "Besiegt Oberhirtin Neloren, Vorarbeiter Llothan, den Schwarmfürsten, den Höhlenpatriarchen, den Wachposten von Rkugamz und die Schnittersphäre in den Dunkelschattenkavernen I innerhalb von 20 Minuten, nachdem das Verlies gestartet wurde. Die Zeit läuft, sobald ein Gruppenmitglied in die Kavernen hinabsteigt.",
["name"] = "Assassine der Dunkelschattenkavernen I",
}
,
[1585] = {
["description"] = "Besiegt Oberhirtin Neloren, Vorarbeiter Llothan, den Schwarmfürsten, den Höhlenpatriarchen, den Wachposten von Rkugamz und die Schnittersphäre in den Dunkelschattenkavernen I (Veteranen), ohne dass ein Gruppenmitglied getötet wird.",
