["description"] = "Besiegt Nahviintaas in Sonnspitz (Veteranen), ohne dass ein Gruppenmitglied mehr als einmal per Zeitverschiebung durch einen Zeitriss springt.",
["name"] = "Im Gleichschritt",
}
,
[2509] = {
["description"] = "Schließt Quests ab, besiegt Anführer und erkundet Gewölbe, um der Retter Elsweyrs zu werden.",
["name"] = "Retter von Elsweyr",
}
,
[2519] = {
["description"] = "Sammelt mumifizierte Alfiqteile aus der Nekropole von Krempen und belebt das grausige Mumienkätzchen wieder.",
["name"] = "Alfiqmumienmeister",
}
,
[2520] = {
["description"] = "Erlangt in Orkruh zehn Stücke seuchendurchtränkter Stoff und benutzt diese, um die Robe des Peryite-Widerlings herzustellen.",
["name"] = "Peryite-Seuchenkleiderflicker",
}
,
[2522] = {
["description"] = "Stürzt die Usurpatorkönigin, bezwingt Mulaamnir und helft dabei, den Adel von Krempen wieder einzusetzen, während eine Schar Drachen das nördliche Elsweyr bedroht.",
["name"] = "Champion von Anequina",
}
,
[2523] = {
["description"] = "Erreicht den maximalen Rang in der Fertigkeitslinie der Diebesgilde.",
["name"] = "Fertigkeitsmeister der Diebesgilde",
}
,
[2524] = {
["description"] = "Erreicht den höchsten Rang der Fertigkeitslinie der Dunklen Bruderschaft.",
["name"] = "Fertigkeitsmeister der Dunklen Bruderschaft",
}
,
[2534] = {
["description"] = "Sammelt Fetzen des unbezahlbaren khajiitischen Wandteppichs, Khajiit der Monde, um die Geschichte zu ehren und die Bewohner Senchals zu inspirieren.",
["name"] = "Geschichtsfetzen",
}
,
[2539] = {
["description"] = "Besiegt Kjarg Hauerkratzer, Schwester Skelga, Vearogh den Schlurfenden, den sturmgeborenen Wiedergänger und den Eiskap-Zirkel in Eiskap.",
["name"] = "Eiskap-Überwältiger",
}
,
[2540] = {
["description"] = "Besiegt Kjarg Hauerkratzer, Schwester Skelga, Vearogh den Schlurfenden, den sturmgeborenen Wiedergänger und den Eiskap-Zirkel in Eiskap (Veteranen).",
["name"] = "Eroberer von Eiskap",
}
,
[2541] = {
["description"] = "Besiegt den Eiskap-Zirkel in Eiskap (Veteranen), nachdem Ihr dessen heiliges Weidentotem niedergebrannt habt.",
["name"] = "Kaltblütiger Mörder",
}
,
[2542] = {
["description"] = "Besiegt Kjarg Hauerkratzer, Schwester Skelga, Vearogh den Schlurfenden, den sturmgeborenen Wiedergänger und den Eiskap-Zirkel innerhalb von 30 Minuten, nachdem Ihr Eiskap (Veteranen) betreten habt. Die Zeit läuft, sobald Ihr in einen Kampf verwickelt werdet.",
["name"] = "Im Thanenschritt",
}
,
[2543] = {
["description"] = "Besiegt zusätzlich zu Kjarg Hauerkratzer, Schwester Skelga, Vearogh den Schlurfenden, dem sturmgeborenen Wiedergänger und dem Eiskap-Zirkel alle Gegner in Eiskap (Veteranen), ohne dass ein Gruppenmitglied getötet wird.",
["name"] = "Fluchgeprüft",
}
,
[2545] = {
["description"] = "Bewältigt die angegebenen Errungenschaften für das Eiskap (Veteranen).",
["name"] = "Herausforderer von Eiskap",
}
,
[2546] = {
["description"] = "Besiegt zusätzlich zu Kjarg Hauerkratzer, Schwester Skelga, Vearogh dem Schlurfenden, dem sturmgeborenen Wiedergänger und dem Eiskap-Zirkel, nachdem dessen Weidentotem verbrannt wurde, alle Gegner in Eiskap (Veteranen) innerhalb von 30 Minuten und ohne dass ein Gruppenmitglied getötet wird. Die Zeit läuft, sobald Ihr die erste Gruppe von Gegnern angreift.",
["name"] = "Kein Frieden für das Böse",
}
,
[2549] = {
["description"] = "Besiegt Hakgrym den Heuler, die Bewahrerin der Feuerkammer, die ewige Ägis, Ondagore den Verrückten und Kjalnar Grabskalde im Unheiligen Grab.",
["name"] = "Sieger des Unheiligen Grabs",
}
,
[2550] = {
["description"] = "Besiegt Hakgrym den Heuler, die Bewahrerin der Feuerkammer, die ewige Ägis, Ondagore den Verrückten und Kjalnar Grabskalde im Unheiligen Grab (Veteranen).",
["name"] = "Eroberer des Unheiligen Grabs",
}
,
[2551] = {
["description"] = "Besiegt Kjalnar Grabskalde im Unheiligen Grab (Veteranen), nachdem Ihr Kjalnars Schädeltotem zerstört habt.",
["name"] = "Schädelschmetterer",
}
,
[2552] = {
["description"] = "Besiegt zusätzlich zu Hakgrym dem Heuler, der Bewahrerin der Feuerkammer, der ewigen Ägis, Ondagore dem Verrückten und Kjalnar Grabskalde alle Gegner im Unheiligen Grab (Veteranen) innerhalb von 30 Minuten. Die Zeit läuft, sobald Ihr in einen Kampf verwickelt werdet. Ihr müsst Vorias Heiligtum nicht betreten.",
["name"] = "Grabräuber",
}
,
[2553] = {
["description"] = "Besiegt zusätzlich zu Hakgrym dem Heuler, der Bewahrerin der Feuerkammer, der ewigen Ägis, Ondagore dem Verrückten und Kjalnar Grabskalde alle Gegner im Unheiligen Grab (Veteranen), ohne dass ein Gruppenmitglied getötet wird. Ihr müsst Vorias Heiligtum nicht betreten.",
["name"] = "Unversehrtes Grab",
}
,
[2554] = {
["description"] = "Bewältigt die angegebenen Errungenschaften für das Unheilige Grab (Veteranen).",
["name"] = "Herausforderer des Unheiligen Grabs",
}
,
[2555] = {
["description"] = "Besiegt innerhalb von 30 Minuten und ohne dass ein Gruppenmitglied getötet wird alle Gegner im Unheiligen Grab (Veteranen) zusätzlich zu Hakgrym dem Heuler, der Bewahrerin der Feuerkammer, der ewigen Ägis, Ondagore dem Verrückten und Kjalnar Grabskalde, nachdem Ihr Kjalnars Schädeltotem zerstört habt. Ihr müsst Vorias Heiligtum nicht betreten. Die Zeit läuft, sobald Ihr die erste Gruppe von Gegnern angreift.",
["name"] = "Dem Tod zum Trotz",
}
,
[2556] = {
["description"] = "Schließt sowohl Eiskap (Veteranen) als auch das Unheilige Grab (Veteranen) ab.",
["name"] = "Höhlenforscher des Gramsturms",
}
,
[2563] = {
["description"] = "Besiegt beide Anführer in der offenen Welt im südlichen Elsweyr.",
["name"] = "Verteidiger von Pellitine",
}
,
[2564] = {
["description"] = "Besiegt den Tempelwächter Iratan den Lichtbringer am Schrein des Neugeschmiedeten.",
["name"] = "Tempelwächterschrecken",
}
,
[2565] = {
["description"] = "Besiegt den ausgestoßenen Adepten Ri\'Atahrashi auf seinem Übungsgelände.",
["name"] = "Ende des Exils",
}
,
[2569] = {
["description"] = "Besiegt die erwachten Trümmer in der Mondgrab-Tempelstadt (Veteranen), ohne dass Ihr einen Hämoheloten mithilfe der Synergie „Sangiin-Opfer“ erschafft.",
