}
,
[2575] = {
["description"] = "Erschlagt in der Mondgrab-Tempelstadt (Veteranen), nachdem Ihr den Sangiin-Hämoheloten verwendet habt, gefräßige Reifzecken mit dem verschiebbaren Stein.",
