}
,
[2577] = {
["description"] = "Trefft 150 Feinde mit Hämoheloten in der Mondgrab-Tempelstadt.",
["name"] = "Blutstürmer",
}
,
[2578] = {
["description"] = "Besiegt Maarselok im Flug im Hort von Maarselok, ohne dass ein Gruppenmitglied durch Fäulekugel oder Fäulnisbecken getroffen wird.",
["name"] = "Augen zum Himmel",
}
,
[2579] = {
["description"] = "Besiegt den Azurfäule-Schlurfer im Hort von Maarselok (Veteranen), während er von Maarseloks Fäulnisbecken erzürnt ist",
