}
,
[2583] = {
["description"] = "Besiegt Maarselok in seinem Nest im Hort von Maarselok (Veteranen), nachdem Ihr alle seine Geißelsaaten gereinigt habt, ohne dass der jeweilige Wirt Selenes „reinigender Schutz“ einsetzt.",
