}
,
[2658] = {
["description"] = "Erbittet die Weisheit eines khajiitischen Legendenhelden auf der Terrasse des Palasts von Senchal, nachdem Ihr die Hauptgeschichte von „Elsweyr“ und „Dragonhold“ abgeschlossen habt.",
["name"] = "Lied eines Helden",
}
,
[2660] = {
["description"] = "Schließt sowohl Eiskap als auch das Unheilige Grab ab.",
["name"] = "Späher des Gramsturms",
}
,
[2670] = {
["description"] = "Besiegt Kjarg Hauerkratzer in Eiskap (Veteranen) mit mindestens drei vollständig ausgebildeten Frostatronachen.",
["name"] = "Eisiges Ende",
}
,
[2671] = {
["description"] = "Entfernt die Eisrüstung von fünfzig Würgern, indem Ihr die abstrahlende Hitze des schmelzenden Schwalls verwendet, um ihnen Schaden zuzufügen.",
["name"] = "Feuerbesen",
}
,
[2672] = {
["description"] = "Besiegt Schwester Skelga in Eiskap (Veteranen), ohne dass Spieler von den Eisspei-Projektilen der Würger getroffen werden.",
["name"] = "Drauf gespuckt",
}
,
[2673] = {
["description"] = "Besiegt Vearogh den Schlurfenden in Eiskap (Veteranen), ohne Rissgeister zu töten.",
["name"] = "Eine offene Anrufung",
}
,
[2674] = {
["description"] = "Besiegt, während Ihr gegen den sturmgeborenen Wiedergänger in Eiskap (Veteranen) kämpft, drei Sturmatronachen innerhalb von jeweils höchstens 3 Sekunden zueinander.",
["name"] = "Der Blitz schlägt dreimal ein",
}
,
[2675] = {
["description"] = "Besiegt den Eiskap-Zirkel in Eiskap (Veteranen), während ein Gruppenmitglied von jedem einzelnen Zauber der Hexen befallen ist.",
["name"] = "Auge des Sturms",
}
,
[2676] = {
["description"] = "Verhindert, dass der Eiskap-Zirkel die Sturmwoge erfolgreich heraufbeschwört, indem Ihr alle vier Schwestern innerhalb von fünf Sekunden nach Beginn des Zaubers unterbrecht.",
["name"] = "Schnell Schweigender",
}
,
[2677] = {
["description"] = "Benutzt Gohllas Riesen in der schweren Fassung von Eiskap (Veteranen), um jede der Schwestern zu töten, während diese erzürnt sind.",
["name"] = "Gewalttätige Befriedung",
}
,
[2678] = {
["description"] = "Erhaltet Zutritt zu Vorias Heiligtum im Unheiligen Grab und besiegt die Bestie darin.",
["name"] = "Klopf, klopf",
}
,
[2679] = {
["description"] = "Besiegt Hakgrym den Heuler im Unheiligen Grab (Veteranen), ohne eine seiner Fleischabscheulichkeiten zu besiegen.",
["name"] = "Unablässiger Hundefänger",
}
,
[2680] = {
["description"] = "Besiegt die Bewahrerin der Feuerkammer, ohne auch nur einmal das korrekte Symbol zu enthüllen.",
["name"] = "Keramikpanik",
}
,
[2681] = {
["description"] = "Besiegt die ewige Ägis, ohne dass der Ring der Klingen die Angriffe eines Gruppenmitglieds abblocken kann oder dass kleinere Ägiden explodieren.",
["name"] = "Zerschmetterte Schilde",
}
,
[2682] = {
["description"] = "Besiegt im Kampf gegen die ewige Ägis im Unheiligen Grab eine kleinere Ägis, direkt nachdem sie mit der Kanalisierung der Schildbrecher-Fähigkeit beginnt und noch bevor diese explodiert.",
["name"] = "Zweite letzte Trennung",
}
,
[2683] = {
["description"] = "Tötet, während Ihr gegen Ondagore den Verrückten im Unheiligen Grab (Veteranen) kämpft, alle Pfleger innerhalb von 5 Sekunden zueinander.",
["name"] = "Pflegererleger",
}
,
[2684] = {
["description"] = "Besiegt Kjalnar Grabskalde im Unheiligen Grab (Veteranen), ohne die getränkten Skelette zu zerstören, bevor sie die stärkenden Kreise erreichen.",
["name"] = "Freie Machtentfaltung",
}
,
[2685] = {
["description"] = "Besiegt Kjalnar Grabskalde, ohne dass ein getränktes Skelett sich stärkt.",
["name"] = "Vernichtende Skelettniederlage",
}
,
[2688] = {
["description"] = "Zerstreut den Gramsturm jeder einzelnen Ritualstätte im westlichen Himmelsrand und in den Graumoorkavernen von Schwarzweite.",
["name"] = "Gramsturmjäger",
}
,
[2690] = {
["description"] = "Zerstreut zehn Gramstürme an Ritualstätten im westlichen Himmelsrand, im Reik oder in Schwarzweite.",
["name"] = "Gramsturmzerstörer",
}
,
[2691] = {
["description"] = "Zerstreut 30 Gramstürme an Ritualstätten im westlichen Himmelsrand, im Reik oder in Schwarzweite.",
["name"] = "Gramsturmvernichter",
}
,
[2694] = {
["description"] = "Besiegt Exarch Kraglen, den Steinbehemoth und Arkasis den irren Alchemisten im Steingarten.",
["name"] = "Steingarten-Überwältiger",
}
,
[2695] = {
["description"] = "Besiegt Exarch Kraglen, den Steinbehemoth und Arkasis den irren Alchemisten im Steingarten (Veteranen).",
["name"] = "Eroberer des Steingartens",
}
,
[2697] = {
["description"] = "Besiegt zusätzlich zu Exarch Kraglen, dem Steinbehemoth und Arkasis dem irren Alchemisten alle Gegner im Steingarten (Veteranen) innerhalb von 25 Minuten. Die Zeit läuft, sobald Ihr die erste Gruppe Verteidiger des Steingartens angreift. Die Vitalisierer-Flusssteuerung könnt Ihr dabei ignorieren.",
["name"] = "Prompter Experimentierer",
}
,
[2698] = {
["description"] = "Besiegt zusätzlich zu Exarch Kraglen, den Steinbehemoth und Arkasis den irren Alchemisten alle Gegner im Steingarten (Veteranen), ohne dass ein Gruppenmitglied getötet wird. Die Vitalisierer-Flusssteuerung könnt Ihr dabei ignorieren.",
["name"] = "Sicherheit geht vor!",
}
,
[2700] = {
["description"] = "Bewältigt die angegebenen Errungenschaften für den Steingarten (Veteranen).",
["name"] = "Herausforderer des Steingartens",
}
,
[2701] = {
["description"] = "Besiegt zusätzlich zu Exarch Kraglen, dem Steinbehemoth und Arkasis dem irren Alchemisten nach dem Hissen der Herausforderungsbanner für sie alle Gegner im Steingarten (Veteranen) innerhalb von 25 Minuten und ohne dass ein Gruppenmitglied getötet wird. Die Vitalisierer-Flusssteuerung könnt Ihr dabei ignorieren. Die Zeit läuft, sobald Ihr die erste Gruppe von Gegnern angreift.",
["name"] = "Wahres Genie",
}
,
[2704] = {
["description"] = "Besiegt die grausige Tindulra, den Blutschrecken, Vaduroth, Talfyg und Fürstin Dorn in Kastell Dorn.",
["name"] = "Sieger von Kastell Dorn",
}
,
[2705] = {
["description"] = "Besiegt die grausige Tindulra, den Blutschrecken, Vaduroth, Talfyg und Fürstin Dorn in Kastell Dorn (Veteranen).",
["name"] = "Eroberer von Kastell Dorn",
}
,
[2706] = {
["description"] = "Besiegt Fürstin Dorn in Kastell Dorn (Veteranen), nachdem Ihr das Herausforderungsbanner gehisst habt.",
["name"] = "Dornauszieher",
}
,
[2707] = {
